<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;class OrderAllocation extends Model {protected $fillable=['order_id','seller_user_id','payout_account_id','provider_subaccount_code','gross_minor','platform_fee_minor','seller_net_minor','currency','settlement_mode','settlement_status'];protected $casts=['gross_minor'=>'integer','platform_fee_minor'=>'integer','seller_net_minor'=>'integer'];public function order():BelongsTo{return $this->belongsTo(Order::class);}public function seller():BelongsTo{return $this->belongsTo(User::class,'seller_user_id');}public function payoutAccount():BelongsTo{return $this->belongsTo(PayoutAccount::class);}}